`centerTab()` for mobile: 
```js
function centerTab(){
  var t = tabButtons[step]; if(!t) return;
  var box = tabsEl;
  if (box.scrollWidth <= box.clientWidth + 2) return;
  var target = t.offsetLeft - (box.clientWidth - t.offsetWidth)/2;
  var max = box.scrollWidth - box.clientWidth;
  target = Math.max(0, Math.min(target, max));
  if (Math.abs(box.scrollLeft - target) < 2) return;
  box.scrollTo({left: target, behavior:'smooth'});
}
```
