Keyboard:
```js
function onKey(e){
  var li = e.target.closest && e.target.closest('li.item');
  if (!li) return;
  var ul = li.parentNode;
  var k = e.key;
  if (k === 'ArrowUp' || k === 'ArrowDown' || k === 'Home' || k === 'End' || k==='PageUp' || k==='PageDown') {
    e.preventDefault();
    var kids=[].slice.call(ul.children);
    var i = kids.indexOf(li);
    var j = i;
    if (k==='ArrowUp'||k==='PageUp') j = Math.max(0, i-1);
    else if (k==='ArrowDown'||k==='PageDown') j = Math.min(kids.length-1, i+1);
    else if (k==='Home') j = 0;
    else j = kids.length-1;
    if (j===i) return;
    if (j < i) ul.insertBefore(li, kids[j]);
    else ul.insertBefore(li, kids[j].nextSibling);
    updateRanks(ul);
    li.focus();
    announce(li, ul);
  }
}
```
