onPointerMove:
```js
function onPointerMove(e){
  if (!drag) return;
  e.preventDefault();
  if (!drag.moved && Math.abs(e.clientY - drag.startY) < 3) return;
  drag.moved = true;
  const { li, ul } = drag;
  const y = e.clientY;
  const siblings = [...ul.children].filter(x => x !== li);
  let target = null;
  for (const s of siblings){
    const r = s.getBoundingClientRect();
    if (y < r.top + r.height/2){ target = s; break; }
  }
  if (target){
    if (li.nextElementSibling !== target) ul.insertBefore(li, target);
  } else if (ul.lastElementChild !== li){
    ul.appendChild(li);
  }
  updateRanks(ul);
  // autoscroll
  const edge = 90;
  if (y < edge) window.scrollBy(0, -14);
  else if (y > window.innerHeight - edge) window.scrollBy(0, 14);
}
```
Edge: if dragging while pointer near top, scroll. PreventDefault in each move — fine.

Note the li.nextElementSibling !== target check: if li is already immediately before target, insertBefore is a no-op; skipping avoids churn. But when inserting before target where li is target's prev sibling, skipping is correct.

onPointerUp:
```js
function onPointerUp(e){
  if (!drag) return;
  const { li, ul, id, moved } = drag;
  drag = null;
  li.classList.remove('is-dragging');
  document.body.classList.remove('dragging');
  window.removeEventListener('pointermove', onPointerMove);
  window.removeEventListener('pointerup', onPointerUp);
  window.removeEventListener('pointercancel', onPointerUp);
  try { ul.releasePointerCapture(id); } catch(_){}
  updateRanks(ul);
  if (moved) announce(li, ul);
}
```

Keyboard:
```js
function onListKeyDown(e){
  const li = e.target.closest('li.item');
  if (!li || li.parentNode !== e.currentTarget) return;
  const ul = e.currentTarget;
  const kids = [...ul.children];
  const i = kids.indexOf(li);
  let j = i;
  switch(e.key){
    case 'ArrowUp': case 'PageUp': j = Math.max(0, i-1); break;
    case 'ArrowDown': case 'PageDown': j = Math.min(kids.length-1, i+1); break;
    case 'Home': j = 0; break;
    case 'End': j = kids.length-1; break;
    default: return;
  }
  e.preventDefault();
  if (j === i) return;
  if (j < i) ul.insertBefore(li, kids[j]);
  else ul.insertBefore(li, kids[j].nextElementSibling);
  updateRanks(ul);
  li.focus({preventScroll:true});
  li.scrollIntoView({block:'nearest'});
  announce(li, ul);
}
```

