function computeScore(){
  const res = {d:0,i:0,s:0,c:0};
  lists.forEach(ul=>{
    const items = ul.children;
    if (!items.length) return;
    const major = items[0].getAttribute('data-type');
    const minor = items[items.length-1].getAttribute('data-type');
    if (major in res) res[major] += 1;
    if (minor in res) res[minor] -= 1;
  });
  return res;
}
