var nativeDrag = null;

function onDragStart(e) {
  if (drag) { e.preventDefault(); return; }
  var li = e.target.closest ? e.target.closest('li.item') : null;
  if (!li) return;
  nativeDrag = { li: li, ul: li.parentNode, moved: false };
  if (e.dataTransfer) {
    try {
      e.dataTransfer.effectAllowed = 'move';
      e.dataTransfer.setData('text/plain', '');
    } catch (_) {}
  }
  li.classList.add('is-dragging');
}

function onDragOver(e) {
  if (!nativeDrag) return;
  var ul = nativeDrag.ul;
  var li = nativeDrag.li;
  if (!ul.contains(e.target) && e.target !== ul) return;
  e.preventDefault();
  nativeDrag.moved = true;

  var y = e.clientY;
  var siblings = Array.prototype.slice.call(ul.children).filter(function (x) { return x !== li; });
  var target = null;

  for (var i = 0; i < siblings.length; i++) {
    var r = siblings[i].getBoundingClientRect();
    if (y < r.top + r.height / 2) { target = siblings[i]; break; }
  }

  if (target) {
    if (li.nextElementSibling !== target) ul.insertBefore(li, target);
  } else if (ul.lastElementChild !== li) {
    ul.appendChild(li);
  }

  updateRanks(ul);
}

function onDrop(e) {
  if (!nativeDrag) return;
  e.preventDefault();
  finishNativeDrag();
}

function finishNativeDrag() {
  if (!nativeDrag) return;
  var li = nativeDrag.li;
  var ul = nativeDrag.ul;
  var moved = nativeDrag.moved;
  nativeDrag = null;
  li.classList.remove('is-dragging');
  updateRanks(ul);
  if (moved) announce(li, ul);
}

